map $uri $frontend_cache_control {
    ~^/assets/    "public, max-age=31536000, immutable";
    /healthz      "no-store";
    /readyz       "no-store";
    ~^/api/       "";
    default       "no-cache";
}

map $request_uri $frontend_api_uri_invalid {
    "~*^[^?]*(/\.\.?(/|\?|$)|//|%2e|%2f|%5c|\x5c)"    1;
    "~^/api/"                                           0;
    default                                             1;
}

server {
    listen 8080 default_server;
    listen [::]:8080 default_server;
    server_name _;

    server_tokens off;
    # Empty in CTF HTTP mode; HTTPS profile trusts only its isolated ingress network.
    include /etc/nginx/slopdns-realip/*.conf;
    absolute_redirect off;
    client_max_body_size 1m;
    client_body_timeout 15s;
    client_header_timeout 15s;
    keepalive_timeout 65s;
    send_timeout 30s;

    root /usr/share/nginx/html;
    index index.html;

    gzip on;
    gzip_vary on;
    gzip_types text/css application/javascript application/json image/svg+xml;

    resolver 127.0.0.11 valid=10s ipv6=off;
    resolver_timeout 5s;

    add_header Cache-Control $frontend_cache_control always;
    add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header Referrer-Policy "no-referrer" always;
    add_header X-Frame-Options "DENY" always;

    error_page 400 494 /__slopdns_errors/400;
    error_page 405 /__slopdns_errors/405;
    error_page 408 /__slopdns_errors/408;
    error_page 413 /__slopdns_errors/413;
    error_page 414 /__slopdns_errors/414;
    error_page 500 /__slopdns_errors/500;
    error_page 501 /__slopdns_errors/501;
    error_page 505 /__slopdns_errors/505;

    location = /__slopdns_errors/400 {
        internal;
        default_type application/json;
        return 400 '{"error":{"code":"bad_request","message":"malformed request"}}';
    }

    location = /__slopdns_errors/405 {
        internal;
        default_type application/json;
        return 405 '{"error":{"code":"bad_request","message":"method not allowed"}}';
    }

    location = /__slopdns_errors/408 {
        internal;
        default_type application/json;
        return 408 '{"error":{"code":"bad_request","message":"request timeout"}}';
    }

    location = /__slopdns_errors/413 {
        internal;
        default_type application/json;
        return 413 '{"error":{"code":"bad_request","message":"request body too large"}}';
    }

    location = /__slopdns_errors/414 {
        internal;
        default_type application/json;
        return 414 '{"error":{"code":"bad_request","message":"request URI too long"}}';
    }

    location = /__slopdns_errors/500 {
        internal;
        default_type application/json;
        return 500 '{"error":{"code":"internal_error","message":"internal error"}}';
    }

    location = /__slopdns_errors/501 {
        internal;
        default_type application/json;
        return 501 '{"error":{"code":"bad_request","message":"not implemented"}}';
    }

    location = /__slopdns_errors/505 {
        internal;
        default_type application/json;
        return 505 '{"error":{"code":"bad_request","message":"HTTP version not supported"}}';
    }

    location = /__slopdns_errors/502 {
        internal;
        default_type application/json;
        return 502 '{"error":{"code":"service_unavailable","message":"The API gateway is unavailable."}}';
    }

    location = /healthz {
        access_log off;
        default_type application/json;
        return 200 '{"status":"ok"}';
    }

    location = /readyz {
        access_log off;
        default_type application/json;
        return 200 '{"status":"ok"}';
    }

    location = /api {
        default_type application/json;
        return 404 '{"error":{"code":"not_found","message":"Not found."}}';
    }

    location /api/ {
        default_type application/json;
        if ($frontend_api_uri_invalid) {
            return 400 '{"error":{"code":"bad_request","message":"non-canonical request path"}}';
    }
        set $gateway_upstream http://gateway:8080;
        proxy_pass $gateway_upstream;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host "";
        proxy_set_header Forwarded "";
        proxy_set_header X-SlopDNS-Assertion "";
        proxy_set_header Connection "";
        proxy_hide_header Content-Security-Policy;
        proxy_hide_header X-Content-Type-Options;
        proxy_hide_header Referrer-Policy;
        proxy_hide_header X-Frame-Options;
        proxy_connect_timeout 5s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;
        error_page 400 494 /__slopdns_errors/400;
        error_page 405 /__slopdns_errors/405;
        error_page 408 /__slopdns_errors/408;
        error_page 413 /__slopdns_errors/413;
        error_page 414 /__slopdns_errors/414;
        error_page 500 /__slopdns_errors/500;
        error_page 501 /__slopdns_errors/501;
        error_page 505 /__slopdns_errors/505;
        error_page 502 504 /__slopdns_errors/502;
    }

    location /assets/ {
        try_files $uri =404;
    }

    location / {
        try_files $uri $uri/ /index.html;
    }
}

