			ss.srv.recordResync(ss.node, "change_log reset detected: "+err.Error())
			return errReset
		case errors.Is(err, store.ErrPruned):
			ss.log.WarnContext(ss.ctx, "session revision was pruned from change_log", slog.Uint64("sent_revision", sent))
			return errPruned
