  1	#!/usr/bin/env python3
  2	"""Create private installation config; never overwrite an existing installation."""
  3	import argparse
  4	import os
  5	from pathlib import Path
  6	import secrets
  7	
  8	PASSWORDS = {
  9	    "POSTGRES_PASSWORD", "SLOPDNS_IAM_OWNER_DB_PASSWORD",
 10	    "SLOPDNS_BACKEND_OWNER_DB_PASSWORD", "SLOPDNS_IAM_DB_PASSWORD",
 11	    "SLOPDNS_BACKEND_DB_PASSWORD", "SLOPDNS_SYNC_DB_PASSWORD",
 12	}
 13	
 14	
 15	def main():
 16	    parser = argparse.ArgumentParser(description=__doc__)
 17	    parser.add_argument("--output", type=Path, default=Path(__file__).resolve().with_name(".env"))
 18	    args = parser.parse_args()
 19	    template = Path(__file__).resolve().with_name(".env.example").read_text()
 20	    lines = []
 21	    for line in template.splitlines():
 22	        key, sep, value = line.partition("=")
 23	        if key in PASSWORDS:
 24	            value = secrets.token_hex(32)
 25	        lines.append(key + sep + value)
 26	    try:
 27	        fd = os.open(args.output, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
 28	    except FileExistsError:
