 28	func TestDatabaseFailureDoesNotRenewFreshnessWithHeartbeat(t *testing.T) {
 29		ctx, cancel := context.WithTimeout(context.Background(), time.Second)
 30		defer cancel()
 31		logger := slog.New(slog.NewTextHandler(io.Discard, nil))
 32		s := &Server{src: failedChangeSource{}, notify: quietNotifier{make(chan struct{})}, opts: Options{Heartbeat: time.Millisecond, DeltaBatch: 10}}
 33		ss := &session{srv: s, ctx: ctx, log: logger, out: make(chan *syncv1.ServerFrame, 1)}
 34		if err := ss.live(1, "anchor"); status.Code(err) != codes.Unavailable {
 35			t.Fatalf("got %v", err)
 36		}
 37		if len(ss.out) != 0 {
