256	func (ss *session) live(sent uint64, anchor string) error {
257		hb := time.NewTicker(ss.srv.opts.Heartbeat)
258		defer hb.Stop()
259		for {
260			wake := ss.srv.notify.Changed()
261			changes, err := ss.srv.src.ChangesAfter(ss.ctx, sent, anchor, ss.srv.opts.DeltaBatch)
262			switch {
263			case errors.Is(err, store.ErrReset):
264				ss.log.ErrorContext(ss.ctx, "change_log reset detected, closing the stream for a full resync", slog.Uint64("sent_revision", sent), slog.Uint64("head_revision", ss.srv.notify.Head()), slog.Any("error", err))
265				ss.srv.recordResync(ss.node, "change_log reset detected: "+err.Error())
266				return errReset
267			case errors.Is(err, store.ErrPruned):
268				ss.log.WarnContext(ss.ctx, "session revision was pruned from change_log", slog.Uint64("sent_revision", sent))
269				return errPruned
270			case err != nil:
271				if ss.ctx.Err() != nil {
272					return context.Cause(ss.ctx)
273				}
274				// A heartbeat renews the DNS node's freshness lease. Do not sign
275				// liveness as freshness while the authoritative database is unreadable.
276				ss.log.WarnContext(ss.ctx, "change_log read failed, closing stale stream", slog.Any("error", err))
277				return status.Error(codes.Unavailable, "change_log is unavailable")
278			}
279			for _, c := range changes {
280				if c.Revision <= sent {
281					continue
282				}
283				for _, p := range c.Problems {
284					ss.log.ErrorContext(ss.ctx, "invalid data left out of a delta", slog.Uint64("revision", c.Revision), slog.Any("error", p))
285				}
286				prev := sent
287				ss.sent.Store(c.Revision)
288				if err := ss.enqueue(syncv1.FrameKind_FRAME_KIND_DELTA, &syncv1.Delta{PrevRevision: prev, Revision: c.Revision, Ops: c.Ops}); err != nil {
289					return err
290				}
291				sent, anchor = c.Revision, c.Fingerprint
292				ss.srv.recordSent(ss.node, sent, anchor)
293			}
294			if err == nil && len(changes) >= ss.srv.opts.DeltaBatch {
295				continue
296			}
297			select {
298			case <-ss.ctx.Done():
299				return context.Cause(ss.ctx)
300			case <-wake:
301			case <-hb.C:
302				if err := ss.enqueue(syncv1.FrameKind_FRAME_KIND_HEARTBEAT, &syncv1.Heartbeat{CurrentRevision: sent, UnixMs: time.Now().UnixMilli()}); err != nil {
303					return err
304				}
305			}
306		}
307	}
